SINA_SMART["anat1-arm"] = {"lecture":"anat1-arm","title":"The arm: compartments and brachial canal","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-arm:e0","text":"Arm: anterior and posterior compartments, separated by medial and lateral septa.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-arm:e1","text":"Anterior: brachialis (→ coronoid), biceps (→ radial tuberosity), coracobrachialis; musculocutaneous n.","topic":"Compartments","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-arm:e2","text":"Biceps: short head coracoid, long head supraglenoid tubercle; flexes and supinates.","topic":"Compartments","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-arm:e3","text":"Posterior: triceps (3 heads → olecranon); radial n.; elbow extension.","topic":"Compartments","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-arm:e4","text":"Radial nerve + profunda brachii in the radial groove.","topic":"Compartments","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-arm:e5","text":"Brachial canal: brachial artery, 2 veins, median and ulnar nerves.","topic":"Brachial canal","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-arm:e6","text":"Brachial artery → radial + ulnar arteries at the elbow.","topic":"Brachial canal","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-arm:e7","text":"Ulnar nerve goes behind the medial septum in the distal third.","topic":"Brachial canal","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"9jhtlo":"a","l0cgd2":"a","lkbum4":"a","1sq7kns":"a","2cjavw":"a","18ui7pp":"a","1xf6s5f":"a","19984i1":"a","xvzn5a":"a","1c0nyl":"a"},"mapCounts":{"verified":0,"auto":10,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-arm:e0":{"s":0,"u":["Arm: anterior and posterior compartments, separated by medial and lateral septa.","A section through the middle of the arm shows anterior and posterior compartments separated by the medial and lateral intermuscular septa attached to the humerus."],"dp":[]},"anat1-arm:e1":{"s":1,"u":["Anterior: brachialis (→ coronoid), biceps (→ radial tuberosity), coracobrachialis; musculocutaneous n.","Anterior (flexors, musculocutaneous nerve ): brachialis (deep; humeral shaft → coronoid process of the ulna ; pure elbow flexor), biceps brachii (superficial; short head from the coracoid , long head from the supraglenoid tubercle → radial tuberosity ; elbow flexion and supination), coracobrachialis (coracoid → medial humerus; flexes the arm)."],"dp":[{"h":"Note","t":"Anterior compartment (biceps, brachialis, coracobrachialis) = musculocutaneous nerve . Posterior (triceps) = radial nerve ."},{"h":"Note","t":"Biceps flexes the elbow and is the most powerful supinator (radial tuberosity). Brachialis is the pure elbow flexor (coronoid process)."}]},"anat1-arm:e2":{"s":1,"u":["Biceps: short head coracoid, long head supraglenoid tubercle; flexes and supinates.","Anterior (flexors, musculocutaneous nerve ): brachialis (deep; humeral shaft → coronoid process of the ulna ; pure elbow flexor), biceps brachii (superficial; short head from the coracoid , long head from the supraglenoid tubercle → radial tuberosity ; elbow flexion and supination), coracobrachialis (coracoid → medial humerus; flexes the arm).","Posterior : triceps brachii : long head (infraglenoid tubercle), lateral head (above the radial groove), medial head (below it) → olecranon ; elbow extension ; radial nerve ."],"dp":[]},"anat1-arm:e3":{"s":1,"u":["Posterior: triceps (3 heads → olecranon); radial n.; elbow extension.","Posterior : triceps brachii : long head (infraglenoid tubercle), lateral head (above the radial groove), medial head (below it) → olecranon ; elbow extension ; radial nerve .","Anterior (flexors, musculocutaneous nerve ): brachialis (deep; humeral shaft → coronoid process of the ulna ; pure elbow flexor), biceps brachii (superficial; short head from the coracoid , long head from the supraglenoid tubercle → radial tuberosity ; elbow flexion and supination), coracobrachialis (coracoid → medial humerus; flexes the arm)."],"dp":[]},"anat1-arm:e4":{"s":1,"u":["Radial nerve + profunda brachii in the radial groove.","The radial nerve and deep brachial artery (profunda brachii) run in the radial groove .","Posterior : triceps brachii : long head (infraglenoid tubercle), lateral head (above the radial groove), medial head (below it) → olecranon ; elbow extension ; radial nerve ."],"dp":[{"h":"Clinical","t":"Radial nerve in the spiral groove (mid-shaft fracture, 'Saturday night palsy'): wrist drop , but triceps is usually spared because its branches leave above the groove."}]},"anat1-arm:e5":{"s":2,"u":["Brachial canal: brachial artery, 2 veins, median and ulnar nerves.","On the medial side, in front of the medial septum, it contains the brachial artery with two brachial veins , the median nerve and the ulnar nerve .","The median nerve travels with the artery, ending medial to it at the elbow."],"dp":[{"h":"Why the brachial artery is used for blood pressure","t":"In the brachial canal the artery runs superficially on the medial side of the arm, pressed against the humerus, at the level of the heart when seated. A cuff around the arm can compress it against the bone, and a stethoscope placed just above the cubital fold hears the flow return, which is why blood pressure is measured there. Source: the lecture's brachial canal section."},{"h":"Note","t":"Brachial canal : brachial artery with two veins, median nerve (crosses the artery lateral → medial) and ulnar nerve (leaves it to pass behind the medial septum)."}]},"anat1-arm:e6":{"s":2,"u":["Brachial artery → radial + ulnar arteries at the elbow.","The brachial artery continues the axillary artery at the lower border of pectoralis major and divides at the elbow into the radial and ulnar arteries ; branches: muscular, profunda brachii (into the radial groove), superior and inferior ulnar collateral arteries.","On the medial side, in front of the medial septum, it contains the brachial artery with two brachial veins , the median nerve and the ulnar nerve ."],"dp":[{"h":"Note","t":"The brachial artery can be compressed against the humerus for tourniquet/BP cuff; it divides into radial and ulnar about 2 cm below the elbow crease , at the neck of the radius."}]},"anat1-arm:e7":{"s":2,"u":["Ulnar nerve goes behind the medial septum in the distal third.","The ulnar nerve is medial and, in the distal third, passes behind the medial intermuscular septum toward the back of the medial epicondyle.","On the medial side, in front of the medial septum, it contains the brachial artery with two brachial veins , the median nerve and the ulnar nerve ."],"dp":[]}},"meta":{"9jhtlo":{"a":"recall","vg":"anat1-arm:e0/recall/1"},"l0cgd2":{"a":"recall","vg":"anat1-arm:e1/recall/1"},"lkbum4":{"a":"recall","vg":"anat1-arm:e1/recall/1"},"1sq7kns":{"a":"recall","vg":"anat1-arm:e1/recall/2"},"2cjavw":{"a":"recall","vg":"anat1-arm:e4/recall/1"},"18ui7pp":{"a":"recall","vg":"anat1-arm:e4/recall/2"},"1xf6s5f":{"a":"recall","vg":"anat1-arm:e4/recall/3"},"19984i1":{"a":"recall","vg":"anat1-arm:e5/recall/1"},"xvzn5a":{"a":"recall","vg":"anat1-arm:e6/recall/1"},"1c0nyl":{"a":"recall","vg":"anat1-arm:e7/recall/1"}},"explRev":"8df145859b0d"};
